double compute_expression(int a, int b, double c) {
    return pow(a, 2) + sqrt(b) * sin(c);
}

int bitwise_transform(int x, int y) {
    return (x << 2) ^ (y >> 1) & 0xF;
}

string process_string(const string& s, int shift) {
    string res = s;
    for (char& ch : res) {
        if (isalpha(ch)) {
            if (islower(ch)) {
                ch = ((ch - 'a' + shift) % 26) + 'a';
            } else {
                ch = ((ch - 'A' + shift) % 26) + 'A';
            }
        }
    }
    return res;
}

