    for(int i=0; i<3; i++) {
        double sum = 0;
        for(int j=0; j<3; j++) {
            sum += exp_matrix[i][j];
        }
        row_sums[i] = sum;
    }

    // Convert row sums to integers by flooring
    vector<int> int_row_sums(3);
    for(int i=0; i<3; i++) {
        int_row_sums[i] = static_cast<int>(floor(row_sums[i]));
    }

    // Perform bitwise XOR on all elements of int_row_sums
    int xor_result = 0;
    for(int i=0; i<3; i++) {
        xor_result ^= int_row_sums[i];
