using namespace std;

double recursive_calc(int n, double base) {
    if (n <= 1) return base;
    double val = recursive_calc(n - 1, base);
    if (n % 3 == 0) {
        return val * log(n);
    } else if (n % 3 == 1) {
        return val + sin(n);
    } else {
        return val - cos(n);
    }
}

