#include <stdio.h>
#include <math.h>

int compute(int *arr, int size, int depth) {
    if (depth <= 0 || size <= 0) {
        return 0;
    }

    int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }

    int mid = size / 2;
    int left = compute(arr, mid, depth - 1);
    int right = compute(arr + mid, size - mid, depth - 1);

    int combined = (left ^ right) + sum;
    return (combined << 1) | ((combined >> 2) & 0x03);
}

int main() {
    int data[] = {7, -2, 15, 8, -3, 12, 5, -1};
    int size = sizeof(data) / sizeof(data[0]);

    int *ptr = data;
    int shifted_value = (*(ptr + 2) << 1) ^ (*(ptr + 5) >> 1);

    double angle = 45.0;
    int trig_result = (int)(100 * (sin(angle * M_PI / 180.0) + cos(angle * M_PI / 180.0)));

    int depth = 3;
    int recursive_result = compute(data, size, depth);

    int result = (shifted_value & 0xFF) + (trig_result | 0x10) - (recursive_result ^ 0xAA);

    printf("Result: %d\n", result);
    return 0;
}

import math

def process_nested_data(data_structure, depth=0):
    if isinstance(data_structure, dict):
        total = 0
        for key, value in data_structure.items():
            if isinstance(value, (list, dict)):
                total += process_nested_data(value, depth + 1)
            else:
                total += value * (depth + 1)
        return total
    elif isinstance(data_structure, list):
        return sum(process_nested_data(item, depth + 1) for item in data_structure)
    else:
        return data_structure * (depth + 1)

def fibonacci(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def transform_string(s):
    vowels = 'aeiouAEIOU'
    transformed = ''
    for i, char in enumerate(s):
        if char in vowels:
        	# Shift vowel by its position in string
            shifted = chr((ord(char) - ord('A' if char.isupper() else 'a') + i) % 26 + ord('A' if char.isupper() else 'a'))
            transformed += shifted
        else:
            # For consonants, use bitwise XOR with position
            xor_val = ord(char) ^ i
            transformed += chr(xor_val % 26 + ord('a'))
    return transformed

