using namespace std;

double recursive_transform(int n, double base) {
    if (n <= 1) return base;
    double val = recursive_transform(n - 1, base);
    if (n % 3 == 0) {
        return val * log(val + 1);
    } else if (n % 3 == 1) {
        return sqrt(val) + sin(val);
    } else {
        return pow(val, 1.0/3.0) + cos(val);
    }
}

int bitwise_chain(int x) {
    x = x << 2;
    x = x ^ 0xF;
    x = x & 0xFF;
    x = x >> 1;
    return x | 0x1;
}

