        int product = 1;
        for (int i = 0; i < size; i++) {
            product *= matrix[i][i];
        }
        return product;
    }

    int getBitwiseSum() {
        int sum = 0;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                sum += (matrix[i][j] & 0xF) | ((matrix[i][j] >> 4) & 0xF);
            }
        }
        return sum;
    }

    double getGeometricMean() {
        double product = 1.0;
        int count = 0;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (matrix[i][j] > 0) {
                    product *= matrix[i][j];
                    count++;
                }
            }
        }
        return pow(product, 1.0/count);
    }
};

int complexFunction(int x, int y) {
    if (x <= 0 || y <= 0) return 0;
    int result = 0;
    for (int i = 1; i <= x; i++) {
        for (int j = 1; j <= y; j++) {
            result += (i * j) ^ (i | j);
        }
    }
    return result;
}

