double compute_recursive(double base, int exp) {
    if (exp == 0) return 1.0;
    if (exp % 2 == 0) {
        double half = compute_recursive(base, exp / 2);
        return half * half;
    }
    return base * compute_recursive(base, exp - 1);
}

