import math

def process_nested_data(data):
    total = 0
    for i, sublist in enumerate(data):
        if i % 2 == 0:
            for val in sublist:
                total += val * (i + 1)
        else:
            for j, val in enumerate(sublist):
                if j % 2 != 0:
                    total -= val << (j // 2)
    return total

def transform_string(s):
    parts = s.split('_')
    transformed = []
    for part in parts:
        if len(part) > 3:
            transformed.append(part[::-1].upper())
        else:
            transformed.append(part.lower() * 2)
    return ''.join(transformed)

