using namespace std;

double compute_expression(double a, double b, int op) {
    switch(op) {
        case 0: return a + b;
        case 1: return a * b;
        case 2: return pow(a, b);
        case 3: return sqrt(abs(a - b));
        default: return 0;
    }
}

int main() {
    map<string, vector<double>> data_map;
    data_map["alpha"] = {2.5, 3.7, 1.2};
    data_map["beta"] = {4.1, 2.8, 5.5};
    data_map["gamma"] = {1.9, 3.3, 2.2};

    double accumulator = 0.0;
    int op_index = 0;

    for(auto& entry : data_map) {
        vector<double>& vec = entry.second;
        for(size_t i = 0; i < vec.size(); ++i) {
            accumulator = compute_expression(accumulator, vec[i], op_index % 4);
            op_index++;
        }
    }

    map<string, map<int, double>> nested_map;
    nested_map["level1"][10] = accumulator;
    nested_map["level1"][20] = accumulator * 1.5;
    nested_map["level2"][30] = accumulator / 2.0;
    nested_map["level2"][40] = pow(accumulator, 1.1);

    double intermediate = 0.0;
    for(auto& outer : nested_map) {
        for(auto& inner : outer.second) {
            intermediate += inner.second;
        }
    }

    vector<map<string, double>> vec_of_maps(2);
    vec_of_maps[0]["x"] = intermediate;
    vec_of_maps[0]["y"] = intermediate * 0.7;
    vec_of_maps[1]["z"] = intermediate / 1.3;
    vec_of_maps[1]["w"] = sqrt(intermediate);

    double final_accumulator = 0.0;
    for(const auto& m : vec_of_maps) {
        for(const auto& pair : m) {
            final_accumulator += pair.second;
        }
    }

    int xor_result = 0;
    for(int i = 1; i <= 10; ++i) {
        xor_result ^= i;
    }

    double final_result = final_accumulator + xor_result;

    cout << "Result: " << final_result << endl;

    return 0;
}

#include <stdio.h>
#include <math.h>

#define PI 3.14159265359

struct Point {
    double x;
    double y;
};

struct Circle {
    struct Point center;
    double radius;
};

struct Rectangle {
    struct Point topLeft;
    struct Point bottomRight;
};

double distance(struct Point p1, struct Point p2) {
    return sqrt(pow(p2.x - p1.x, 2) + pow(p2.y - p1.y, 2));
}

int main() {
    struct Circle c1 = {{0.0, 0.0}, 5.0};
    struct Circle c2 = {{8.0, 0.0}, 3.0};

    struct Rectangle rect = {{-2.0, 2.0}, {10.0, -3.0}};

    double d = distance(c1.center, c2.center);
    int circles_intersect = (d <= (c1.radius + c2.radius)) && (d >= fabs(c1.radius - c2.radius));

    double area_rect = fabs((rect.bottomRight.x - rect.topLeft.x) * (rect.bottomRight.y - rect.topLeft.y));

    double combined_area = area_rect + PI * (pow(c1.radius, 2) + pow(c2.radius, 2));

    int grid_points = 0;
    for (int i = (int)rect.topLeft.x; i <= (int)rect.bottomRight.x; i++) {
        for (int j = (int)rect.bottomRight.y; j <= (int)rect.topLeft.y; j++) {
            struct Point p = {i, j};
            double dist_c1 = distance(p, c1.center);
            double dist_c2 = distance(p, c2.center);
            if (dist_c1 <= c1.radius || dist_c2 <= c2.radius) {
                grid_points++;
            }
        }
    }

    double result = combined_area;
    if (circles_intersect) {
        result += 100;
    } else {
        result -= 50;
    }

    result = result * grid_points;

    printf("Result: %.0f\n", result);

    return 0;
}
